/* ===== FONTS ===== */
@import url('https://fonts.googleapis.com/css2?family=Audiowide&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Anton&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Raleway:wght@100..900&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Pacifico&display=swap');

/* ===== COLORS ===== */
/* 
primary   #042940
secondary #005C53
accent1   #DBF227
accent2   #DB8655
accent3   #62771B
black     #262406
white     #ffffff
*/

/* ===== BASE ===== */
body {
  background-color: #ffffff;
  color: #262406;
  font-family: 'Raleway', sans-serif;
}

a {
  color: #005C53;
}

/* ===== HEADINGS ===== */
h1 {
  color: #042940;
  font-family: 'Audiowide', sans-serif;
  font-size: 3rem;
  font-weight: 400;
}

h2 {
  color: #005C53;
  font-family: 'Raleway', sans-serif;
  font-size: 2rem;
  font-weight: 600;
}

h3 {
  color: #005C53;
  font-family: 'Raleway', sans-serif;
  font-size: 1.5rem;
  font-weight: 500;
}

/* ===== NAVBAR ===== */
.navbar {
  background-color: #042940 !important;
}

.navbar .navbar-brand {
  font-family: 'Audiowide', sans-serif;
  font-size: 2rem;
}

.navbar-nav .nav-link {
  color: #DB8655 !important;
  font-family: 'Raleway', sans-serif;
  font-size: 1.2rem;
}

.navbar-nav .nav-link:hover {
  color: #DBF227 !important;
}

/* ===== RESEARCH QUESTION ===== */
.research-question {
  font-family: 'Raleway', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  color: #DB8655;
  text-transform: uppercase;
}

/* ===== SIDEBAR (Shiny wellPanel equivalent) ===== */
.well {
  background-color: #f8f9fa;
  border-radius: 10px;
  border: 1px solid #ddd;
}

/* ===== BUTTONS ===== */
.btn {
  background-color: #042940;
  color: #DBF227;
  border: none;
}

.btn:hover {
  background-color: #005C53;
  color: #DBF227;
}

/* ===== TEACHING LIST ===== */
.teaching .course-entry {
  display: flex;
  flex-direction: row;
  line-height: 1.3;
  margin-bottom: 3em;
  column-gap: 0.7em;
}

.teaching .course-entry .body {
  flex: 1 1 auto;
}

.teaching .course-entry .logo {
  flex: 0 0 140px;
}

.teaching .course-entry .logo img {
  width: 100%;
}

.teaching .course-entry .course-title {
  font-weight: 500;
  font-size: 1.25em;
}

.teaching .course-entry .course-details {
  font-weight: 300;
  font-size: 0.9em;
}

.teaching .course-entry .course-description {
  font-weight: 300;
  font-size: 1.1em;
}

.teaching .course-entry .course-role {
  font-weight: 500;
}

.teaching .course-entry ul.course-links {
  list-style: none;
  padding: 0;
}

.teaching .course-entry ul.course-links li {
  display: inline-block;
  background-color: #042940;
  margin: 0 0.2em 0.4em 0;
  padding: 0.2em 0.4em;
  font-size: 0.85em;
  border-radius: 0.25rem;
}

.teaching .course-entry ul.course-links li a {
  color: #DBF227;
  text-decoration: none;
}

/* ===== HERO ===== */
.hero-container {
  overflow: hidden;
  position: relative;
  max-height: 52vh;
  height: 52vh;
}

.hero-image {
  position: absolute;
  background-size: cover;
  height: 100%;
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background-repeat: no-repeat;
}

.hero-title-top {
  font-size: 100px;
  color: #ffffff;
  font-weight: bold;
}

.hero-title-bottom {
  font-size: 100px;
  color: #EEECEA;
  font-weight: bold;
}

/* ===== FOOTER ===== */
footer {
  background-color: #005C53;
  color: #DBF227;
  padding: 20px;
  text-align: center;
}

/* Footer credits */
.footer-credits {
  font-size: 0.85em;
  color: #DBF227;        /* accent1 (bright lime) */
  line-height: 1.5;
}

.footer-credits strong {
  color: #DB8655;        /* accent2 (warm highlight) */
}

/* ===== NavBar ===== */

.navbar {
  background-color: #042940 !important;
  padding-top: 15px;
  padding-bottom: 15px;
}

.navbar .navbar-brand {
  font-family: 'Audiowide', sans-serif;
  font-size: 1.5rem;
  color: #DB8655;
  display: flex;
  align-items: center;
}

.navbar-nav .nav-link {
  color: #DB8655 !important;
}

.navbar-nav .nav-link:hover {
  color: #DBF227 !important;
}

/* NavBar logo */
.navbar-logo {
  height: 70px;
  margin-right: 10px;
}

/* ===== NAVBAR TABS ===== */

/* Make tabs look like part of navbar */
.navbar-nav .nav-link {
  color: #DB8655 !important;
  font-family: 'Raleway', sans-serif;
  font-size: 1.2rem;
  background: none !important;
  border: none !important;
}

/* Hover */
.navbar-nav .nav-link:hover {
  color: #DBF227 !important;
  background: none !important;
}

/* Active tab (THIS is the key one) */
.navbar-nav .nav-link.active,
.navbar-nav > .active > a {
  color: #DBF227 !important;
  background-color: transparent !important;
  border-bottom: 3px solid #DB8655;
}
